-- P1-02 P5 AW21-24 NOR-02/03: standardisation and direct normal probabilities.
-- Standard normal probabilities rounded to 4 d.p.; original iClub-authored content only.
begin;
insert into private.exam_prep_content_versions(program_version_id,content_version,component_code,release_label,status,source_policy)
select pv.id,'p5_aw21_24_nor02_03_v1','P5','P5 AW21-24 NOR-02/03 standardisation and probabilities','draft','Original iClub content only; Cambridge 9709 official syllabus defines scope; Complete Probability & Statistics 1 is mapping/teaching reference only; no protected source wording copied. Standard normal values rounded to 4 d.p.'
from private.exam_prep_program_versions pv where pv.program_key='math_as_p1_p5' and pv.version_key='p1_p5_canonical_v1_0'
on conflict(program_version_id,content_version) do nothing;

with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw21_24_nor02_03_v1' and component_code='P5' and status='draft'), src(skill,k,role,diff,qen,qru,quz,o_en,o_ru,o_uz,ans,een,eru,euz,secs) as (values
('P5-NOR-02','P5NOR02-D01','diagnostic','medium','X~N(50,16). What z-value corresponds to X=58?','X~N(50,16). Какому z соответствует X=58?','X~N(50,16). X=58 ga qaysi z mos?','["2","0.5","8","4"]','["2","0,5","8","4"]','["2","0.5","8","4"]','A','The second normal parameter is variance, so sigma=4. Hence z=(58-50)/4=2.','Второй параметр — дисперсия, поэтому sigma=4. z=(58-50)/4=2.','Ikkinchi parametr dispersiya, sigma=4. z=(58-50)/4=2.',45),
('P5-NOR-02','P5NOR02-L01','learning','easy','X~N(100,25). What z-value corresponds to X=90?','X~N(100,25). Какому z соответствует X=90?','X~N(100,25). X=90 ga qaysi z mos?','["-2","-0.4","2","-10"]','["-2","-0,4","2","-10"]','["-2","-0.4","2","-10"]','A','sigma=5, so z=(90-100)/5=-2.','sigma=5, поэтому z=-2.','sigma=5, demak z=-2.',30),
('P5-NOR-02','P5NOR02-L02','learning','medium','For standard normal Z, find P(Z<1.00) to 4 d.p.','Для стандартной нормальной Z найдите P(Z<1,00) до 4 знаков.','Standart normal Z uchun P(Z<1.00) ni 4 xonagacha toping.','["0.8413","0.1587","0.9772","0.5000"]','["0,8413","0,1587","0,9772","0,5000"]','["0.8413","0.1587","0.9772","0.5000"]','A','Phi(1.00)=0.8413.','Phi(1,00)=0,8413.','Phi(1.00)=0.8413.',30),
('P5-NOR-02','P5NOR02-L03','learning','medium','For standard normal Z, find P(Z>1.50) to 4 d.p.','Для стандартной нормальной Z найдите P(Z>1,50) до 4 знаков.','Standart normal Z uchun P(Z>1.50) ni 4 xonagacha toping.','["0.0668","0.9332","0.1587","0.0228"]','["0,0668","0,9332","0,1587","0,0228"]','["0.0668","0.9332","0.1587","0.0228"]','A','P(Z>1.5)=1-Phi(1.5)=1-0.9332=0.0668.','P(Z>1,5)=1-0,9332=0,0668.','P(Z>1.5)=1-0.9332=0.0668.',35),
('P5-NOR-02','P5NOR02-R01','retest','easy','X~N(20,9). What z-value corresponds to X=23?','X~N(20,9). Какому z соответствует X=23?','X~N(20,9). X=23 ga qaysi z mos?','["1","1/3","3","-1"]','["1","1/3","3","-1"]','["1","1/3","3","-1"]','A','sigma=3, so z=(23-20)/3=1.','sigma=3, z=1.','sigma=3, z=1.',25),
('P5-NOR-02','P5NOR02-R02','retest','medium','For standard normal Z, find P(Z<-0.50) to 4 d.p.','Для стандартной нормальной Z найдите P(Z<-0,50) до 4 знаков.','Standart normal Z uchun P(Z<-0.50) ni 4 xonagacha toping.','["0.3085","0.6915","0.1915","0.5000"]','["0,3085","0,6915","0,1915","0,5000"]','["0.3085","0.6915","0.1915","0.5000"]','A','By symmetry, Phi(-0.5)=1-Phi(0.5)=1-0.6915=0.3085.','По симметрии Phi(-0,5)=1-0,6915=0,3085.','Simmetriya bo‘yicha Phi(-0.5)=1-0.6915=0.3085.',35),
('P5-NOR-02','P5NOR02-M01','mixed','medium','X~N(30,4). Find P(X>32) to 4 d.p.','X~N(30,4). Найдите P(X>32) до 4 знаков.','X~N(30,4). P(X>32) ni 4 xonagacha toping.','["0.1587","0.8413","0.0228","0.5000"]','["0,1587","0,8413","0,0228","0,5000"]','["0.1587","0.8413","0.0228","0.5000"]','A','sigma=2, so X=32 gives z=1. Therefore P(X>32)=P(Z>1)=0.1587.','sigma=2, z=1. Поэтому P(X>32)=0,1587.','sigma=2, z=1. Demak P(X>32)=0.1587.',40),

('P5-NOR-03','P5NOR03-D01','diagnostic','medium','X~N(50,100). Find P(X<60) to 4 d.p.','X~N(50,100). Найдите P(X<60) до 4 знаков.','X~N(50,100). P(X<60) ni 4 xonagacha toping.','["0.8413","0.1587","0.9772","0.5000"]','["0,8413","0,1587","0,9772","0,5000"]','["0.8413","0.1587","0.9772","0.5000"]','A','sigma=10 and z=(60-50)/10=1, so P(X<60)=Phi(1)=0.8413.','sigma=10, z=1, поэтому P(X<60)=0,8413.','sigma=10, z=1, demak P(X<60)=0.8413.',45),
('P5-NOR-03','P5NOR03-L01','learning','easy','X~N(20,16). Find P(X>24) to 4 d.p.','X~N(20,16). Найдите P(X>24) до 4 знаков.','X~N(20,16). P(X>24) ni 4 xonagacha toping.','["0.1587","0.8413","0.5000","0.0228"]','["0,1587","0,8413","0,5000","0,0228"]','["0.1587","0.8413","0.5000","0.0228"]','A','sigma=4 gives z=1. Upper tail=1-0.8413=0.1587.','sigma=4, z=1. Верхний хвост=0,1587.','sigma=4, z=1. Yuqori tail=0.1587.',35),
('P5-NOR-03','P5NOR03-L02','learning','medium','X~N(100,25). Find P(95<X<105) to 4 d.p.','X~N(100,25). Найдите P(95<X<105) до 4 знаков.','X~N(100,25). P(95<X<105) ni 4 xonagacha toping.','["0.6827","0.3413","0.8413","0.9545"]','["0,6827","0,3413","0,8413","0,9545"]','["0.6827","0.3413","0.8413","0.9545"]','A','sigma=5, so the bounds are z=-1 and z=1. Probability=Phi(1)-Phi(-1)=0.8413-0.1587=0.6826, conventionally 0.6827 with unrounded values.','sigma=5, границы z=-1 и z=1. По неокруглённым значениям вероятность 0,6827.','sigma=5, chegaralar z=-1 va 1. Aniq qiymatlar bilan ehtimol 0.6827.',45),
('P5-NOR-03','P5NOR03-L03','learning','medium','X~N(10,4). Find P(X<7) to 4 d.p.','X~N(10,4). Найдите P(X<7) до 4 знаков.','X~N(10,4). P(X<7) ni 4 xonagacha toping.','["0.0668","0.9332","0.1587","0.3085"]','["0,0668","0,9332","0,1587","0,3085"]','["0.0668","0.9332","0.1587","0.3085"]','A','sigma=2 gives z=(7-10)/2=-1.5, so Phi(-1.5)=0.0668.','sigma=2, z=-1,5, поэтому вероятность 0,0668.','sigma=2, z=-1.5, ehtimol 0.0668.',40),
('P5-NOR-03','P5NOR03-R01','retest','easy','X~N(30,9). Find P(X>33) to 4 d.p.','X~N(30,9). Найдите P(X>33) до 4 знаков.','X~N(30,9). P(X>33) ni 4 xonagacha toping.','["0.1587","0.8413","0.3085","0.0228"]','["0,1587","0,8413","0,3085","0,0228"]','["0.1587","0.8413","0.3085","0.0228"]','A','sigma=3 and z=1; upper tail is 0.1587.','sigma=3, z=1; верхний хвост 0,1587.','sigma=3, z=1; yuqori tail 0.1587.',30),
('P5-NOR-03','P5NOR03-R02','retest','medium','For standard normal Z, find P(-0.5<Z<1) to 4 d.p.','Для стандартной нормальной Z найдите P(-0,5<Z<1) до 4 знаков.','Standart normal Z uchun P(-0.5<Z<1) ni 4 xonagacha toping.','["0.5328","0.1498","0.6915","0.8413"]','["0,5328","0,1498","0,6915","0,8413"]','["0.5328","0.1498","0.6915","0.8413"]','A','Probability=Phi(1)-Phi(-0.5)=0.8413-0.3085=0.5328.','Вероятность=0,8413-0,3085=0,5328.','Ehtimol=0.8413-0.3085=0.5328.',35),
('P5-NOR-03','P5NOR03-M01','mixed','hard','X~N(80,16). Find P(76<X<88) to 4 d.p.','X~N(80,16). Найдите P(76<X<88) до 4 знаков.','X~N(80,16). P(76<X<88) ni 4 xonagacha toping.','["0.8186","0.1359","0.8413","0.9772"]','["0,8186","0,1359","0,8413","0,9772"]','["0.8186","0.1359","0.8413","0.9772"]','A','sigma=4, giving z=-1 and z=2. Probability=Phi(2)-Phi(-1)=0.9772-0.1587=0.8185, or 0.8186 using unrounded values.','sigma=4, z=-1 и 2. По неокруглённым значениям вероятность 0,8186.','sigma=4, z=-1 va 2. Aniq qiymatlar bilan ehtimol 0.8186.',55)
)
