with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw21_24_nor02_03_v1' and status='draft'), keys(skill,k,role) as (values
('P5-NOR-02','P5NOR02-D01','diagnostic'),('P5-NOR-02','P5NOR02-L01','learning'),('P5-NOR-02','P5NOR02-L02','learning'),('P5-NOR-02','P5NOR02-L03','learning'),('P5-NOR-02','P5NOR02-R01','retest'),('P5-NOR-02','P5NOR02-R02','retest'),('P5-NOR-02','P5NOR02-M01','mixed'),
('P5-NOR-03','P5NOR03-D01','diagnostic'),('P5-NOR-03','P5NOR03-L01','learning'),('P5-NOR-03','P5NOR03-L02','learning'),('P5-NOR-03','P5NOR03-L03','learning'),('P5-NOR-03','P5NOR03-R01','retest'),('P5-NOR-03','P5NOR03-R02','retest'),('P5-NOR-03','P5NOR03-M01','mixed'))
insert into private.exam_prep_question_content_meta(content_version_id,content_key,question_id,primary_skill_code,secondary_skill_codes,reserve_role,exposure_state,lifecycle_state,originality_attestation,provenance_note,official_scope_ref,coursebook_mapping_ref,copyright_status,qa_scope_status,qa_math_status,qa_language_status,qa_technical_status,diagnostic_rule_status,question_snapshot_md5)
select cv.id,k.k,q.id,k.skill,'{}'::text[],k.role,'withheld','draft','Original iClub-authored content; no protected source wording copied.','Authored for p5_aw21_24_nor02_03_v1 from canonical normal standardisation/probability intent.','Cambridge 9709 2026-2027 v4; P5 5.5 The normal distribution','Complete Probability & Statistics 1; Normal distribution calculations (mapping only)','pending','pending','pending','pending','pending',case when k.role='diagnostic' then 'pending' else 'not_applicable' end,md5(concat_ws(chr(31),q.id::text,q.subject_id::text,coalesce(q.topic,''),coalesce(q.subtopic,''),coalesce(q.difficulty,''),coalesce(q.qtype,''),coalesce(q.question_text,''),coalesce(q.options_text,''),coalesce(q.correct_answer,''),coalesce(q.explanation,''),coalesce(q.image_url,''),coalesce(q.is_active::text,''),coalesce(q.question_text_ru,''),coalesce(q.question_text_uz,''),coalesce(q.question_text_en,''),coalesce(q.options_text_ru,''),coalesce(q.options_text_uz,''),coalesce(q.options_text_en,''),coalesce(q.explanation_ru,''),coalesce(q.explanation_uz,''),coalesce(q.explanation_en,''),coalesce(q.book_ref,''),coalesce(q.time_limit_sec::text,''),coalesce(q.quality_flag,''),coalesce(q.quality_status,''))) from cv cross join keys k join public.questions q on q.book_ref='ExamPrep:P5:p5_aw21_24_nor02_03_v1:'||k.k on conflict(content_version_id,content_key) do nothing;

with meta as (select m.id,m.content_key,m.primary_skill_code from private.exam_prep_question_content_meta m join private.exam_prep_content_versions cv on cv.id=m.content_version_id where cv.content_version='p5_aw21_24_nor02_03_v1' and m.reserve_role='diagnostic'), r(ckey,match,dcode,mtype,fen,fru,fuz,nen,nru,nuz) as (values
('P5NOR02-D01','B','uses_variance_as_sigma','concept','The second normal parameter is sigma^2=16, so sigma=4. Dividing by 16 gives the wrong z-scale.','Второй параметр sigma^2=16, поэтому sigma=4. Делить на 16 нельзя.','Ikkinchi parametr sigma^2=16, sigma=4. 16 ga bo‘lish noto‘g‘ri.','Take the square root of the variance before standardising.','Перед стандартизацией извлеките корень из дисперсии.','Standartlashdan oldin dispersiyadan ildiz oling.'),
('P5NOR02-D01','C','subtracts_mean_only','method','58-50=8 is the raw displacement, not a z-score. A z-score measures displacement in standard deviations.','58-50=8 — исходное отклонение, не z. z измеряет число стандартных отклонений.','58-50=8 xom farq, z emas. z standart og‘ishlar sonini o‘lchaydi.','Divide the centred value by sigma.','Разделите центрированное значение на sigma.','Markazlangan qiymatni sigma ga bo‘ling.'),
('P5NOR02-D01','D','uses_sigma_without_centering','method','4 is the standard deviation itself, not the standardised value of 58.','4 — само стандартное отклонение, а не z для 58.','4 standart og‘ishning o‘zi, 58 uchun z emas.','Use z=(x-mu)/sigma.','Используйте z=(x-mu)/sigma.','z=(x-mu)/sigma ni ishlating.'),
('P5NOR03-D01','B','chooses_wrong_tail','concept','0.1587 is P(Z>1), but the event X<60 corresponds to Z<1.','0,1587 — это P(Z>1), но X<60 соответствует Z<1.','0.1587 P(Z>1), lekin X<60 Z<1 ga mos.','Sketch or label the requested tail before reading the table.','Перед чтением таблицы отметьте нужный хвост.','Jadvaldan oldin kerakli tail ni belgilang.'),
('P5NOR03-D01','C','wrong_standardisation_scale','method','0.9772 corresponds to z=2, but (60-50)/10=1.','0,9772 соответствует z=2, но (60-50)/10=1.','0.9772 z=2 ga mos, lekin (60-50)/10=1.','Compute z explicitly before using a probability value.','Сначала явно вычислите z.','Avval z ni aniq hisoblang.'),
('P5NOR03-D01','D','assumes_cutoff_at_mean','concept','Probability below the mean is 0.5, but 60 is one standard deviation above the mean 50.','Вероятность ниже среднего 0,5, но 60 находится на одно sigma выше среднего 50.','O‘rtachadan past ehtimol 0.5, lekin 60 o‘rtachadan bir sigma yuqori.','Locate the cutoff relative to mu and sigma.','Определите положение границы относительно mu и sigma.','Chegarani mu va sigma ga nisbatan joylashtiring.'))
insert into private.exam_prep_diagnostic_rules(content_meta_id,rule_version,answer_kind,answer_match,distractor_code,mistake_type,weak_skill_code,feedback_en,feedback_ru,feedback_uz,next_action_en,next_action_ru,next_action_uz,status,approved_at)
