('p5_nor02_03_diagnostic','diagnostic','P5 NOR-02/03 normal calculation diagnostic','Диагностика P5 NOR-02/03: нормальные вычисления','P5 NOR-02/03 normal hisob diagnostikasi'),('p5_nor02_learning','learning','Normal standardisation learning','Стандартизация normal: обучение','Normal standartlash: o‘rganish'),('p5_nor03_learning','learning','Direct normal probabilities learning','Прямые normal probabilities: обучение','To‘g‘ridan normal ehtimollar: o‘rganish'),('p5_nor02_retest','retest','NOR-02 delayed retest','NOR-02 отложенный ретест','NOR-02 kechiktirilgan retest'),('p5_nor03_retest','retest','NOR-03 delayed retest','NOR-03 отложенный ретест','NOR-03 kechiktirilgan retest'),('p5_nor02_03_mixed','mixed','NOR-02/03 mixed normal transfer','NOR-02/03 смешанный normal перенос','NOR-02/03 mixed transfer'))
