('p5_nor02_03_diagnostic',1,'P5NOR02-D01',null,'P5-NOR-02','diagnostic',true),('p5_nor02_03_diagnostic',2,'P5NOR03-D01',null,'P5-NOR-03','diagnostic',true),
('p5_nor02_learning',1,'P5NOR02-L01',null,'P5-NOR-02','learning',false),('p5_nor02_learning',2,'P5NOR02-L02',null,'P5-NOR-02','learning',false),('p5_nor02_learning',3,'P5NOR02-L03',null,'P5-NOR-02','learning',false),('p5_nor02_learning',4,null,'P5NOR02-W01','P5-NOR-02','written',false),
('p5_nor03_learning',1,'P5NOR03-L01',null,'P5-NOR-03','learning',false),('p5_nor03_learning',2,'P5NOR03-L02',null,'P5-NOR-03','learning',false),('p5_nor03_learning',3,'P5NOR03-L03',null,'P5-NOR-03','learning',false),('p5_nor03_learning',4,null,'P5NOR03-W01','P5-NOR-03','written',false),
('p5_nor02_retest',1,'P5NOR02-R01',null,'P5-NOR-02','retest',true),('p5_nor03_retest',1,'P5NOR03-R01',null,'P5-NOR-03','retest',true),
